const separateParenGroups = (paren_string) => {
  const result = [];
  let currentGroup = '';
  let balance = 0;

  // Remove all spaces from the input string
  const cleanedString = paren_string.replace(/\s+/g, '');

  for (const char of cleanedString) {
    currentGroup += char;
    if (char === '(') {
      balance++;
    } else if (char === ')') {
      balance--;
    }

    // When balance returns to 0, a top-level group has been closed
    if (balance === 0 && currentGroup.length > 0) {
      result.push(currentGroup);
      currentGroup = '';
    }
  }

  return result;
};
```

