const parseNestedParens = (paren_string) => {
  return paren_string.split(' ').map(group => {
    let maxDepth = 0;
    let currentDepth = 0;

    for (const char of group) {
      if (char === '(') {
        currentDepth++;
        if (currentDepth > maxDepth) {
          maxDepth = currentDepth;
        }
      } else if (char === ')') {
        currentDepth--;
      }
    }

    return maxDepth;
  });
};
```

