    'zero': 0,
    'one': 1,
    'two': 2,
    'three': 3,
    'four': 4,
    'five': 5,
    'six': 6,
    'seven': 7,
    'eight': 8,
    'nine': 9
  };

  const reverseMap = Object.fromEntries(
    Object.entries(map).map(([key, value]) => [value, key])
  );

  return numbers
    .split(' ')
    .sort((a, b) => map[a] - map[b])
    .join(' ');
};

