const primeFib = (n) => {
  var isPrime = function (p) {
    if (p < 2)
      return false;
    for (let k = 2; k <= Math.sqrt(p); k++) {
      if (p % k == 0)
        return false;
    }
    return true;
  }

  var f = [0, 1];
  var count = 0;
  while (true) {
    let nextFib = f[f.length - 1] + f[f.length - 2];
    f.push(nextFib);
    if (isPrime(nextFib)) {
      count++;
    }
    if (count === n) {
      return nextFib;
    }
  }
}
