  // Create a copy to avoid mutating the original array
  const arr = [...array];

  // Calculate sum of first and last index values
  const tot = arr[0] + arr[arr.length - 1];
  const isOdd = tot % 2 !== 0;

  // Sort ascending if odd, descending if even
  arr.sort((a, b) => {
    if (isOdd) {
      return a - b;
    } else {
      return b - a;
    }
  });

  return arr;
};
