const nextSmallest = (lst) => {
  if (!lst || lst.length < 2) {
    return null;
  }

  // Create a copy to avoid mutating the original input array
  let arr = [...lst];

  // Selection sort to order the array
  for (let j = 0; j < arr.length; j++) {
    let ind = j;
    for (let k = j + 1; k < arr.length; k++) {
      if (arr[k] < arr[ind]) {
        ind = k;
      }
    }
    let tmp = arr[j];
    arr[j] = arr[ind];
    arr[ind] = tmp;
  }

  let smallest = arr[0];
  let pt = 1;

  // Find the first element strictly greater than the smallest
  while (pt < arr.length) {
    if (arr[pt] > smallest) {
      return arr[pt];
    }
    pt++;
  }

  return null;
};
