const encode = (message) => {
  const vowels = 'aeiouAEIOU';

  return message.split('').map(char => {
    // Swap case
    let swapped = char === char.toUpperCase() 
      ? char.toLowerCase() 
      : char.toUpperCase();

    // Check if the original character was a vowel
    if (vowels.includes(char)) {
      // Get the character code of the swapped case version
      // and move it 2 places ahead in the alphabet
      return String.fromCharCode(swapped.charCodeAt(0) + 2);
    }

    return swapped;
  }).join('');
};
