const chooseNum = (x, y) => {
  if (x > y) {
    return -1;
  }

  // Start from the upper bound and move downwards
  let current = Math.floor(y);

  // If the current number is odd, move to the even number immediately below it
  if (current % 2 !== 0) {
    current--;
  }

  // Check if the resulting even number is within the range [x, y]
  if (current >= x) {
    return current;
  }

  return -1;
};
```

