const closestInteger = (value) => {
  const num = parseFloat(value);

  // Math.round() in JS rounds .5 towards positive infinity (e.g., -14.5 becomes -14).
  // To round away from zero, we handle positive and negative numbers separately.
  if (num >= 0) {
    return Math.round(num);
  } else {
    // For negative numbers, we use Math.round on the absolute value and then negate it.
    // This ensures -14.5 becomes -15.
    return -Math.round(Math.abs(num));
  }
};
```

