const roundedAvg = (n, m) => {
  if (n > m) {
    return -1;
  }

  // The sum of integers from n to m is an arithmetic series:
  // Sum = (count * (first + last)) / 2
  // Average = Sum / count = (n + m) / 2
  const avg = (n + m) / 2;
  const rounded = Math.round(avg);

  // Convert the rounded average to a binary string prefixed with '0b'
  return '0b' + rounded.toString(2);
};
