const byLength = (arr) => {
  const names = ["One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine"];

  // Filter integers between 1 and 9 inclusive
  const filtered = arr.filter(num => num >= 1 && num <= 9);

  // Sort in ascending order
  filtered.sort((a, b) => a - b);

  // Reverse the sorted array
  filtered.reverse();

  // Map digits to their corresponding names
  return filtered.map(num => names[num - 1]);
};
```

