const countNums = (arr) => {
  let p = 0;
  for (let i = 0; i < arr.length; i++) {
    let h = arr[i];
    if (h > 0) {
      p++;
      continue;
    }
    if (h === 0) {
      continue;
    }

    let k = 0;
    let temp = Math.abs(h);

    // Extract digits from right to left
    // The leftmost digit will be handled separately to apply the negative sign
    while (temp >= 10) {
      k += temp % 10;
      temp = Math.floor(temp / 10);
    }

    // The remaining 'temp' is the first digit. 
    // Since the original number was negative, the first digit is negative.
    k -= temp;

    if (k > 0) {
      p++;
    }
  }
  return p;
};
