const exchange = (lst1, lst2) => {
  // Count how many odd numbers are currently in lst1.
  // These are the elements that MUST be replaced by even numbers from lst2.
  const oddInLst1 = lst1.filter(num => num % 2 !== 0).length;

  // Count how many even numbers are available in lst2.
  // These are the only elements that can replace the odd numbers in lst1.
  const evenInLst2 = lst2.filter(num => num % 2 === 0).length;

  // If the number of even elements in lst2 is greater than or equal to 
  // the number of odd elements in lst1, we can make lst1 all even.
  return evenInLst2 >= oddInLst1 ? "YES" : "NO";
};
