const histogram = (test) => {
  if (test === '') {
    return {};
  }

  const counts = {};
  const letters = test.split(/\s+/);

  for (const char of letters) {
    if (char === '') continue;
    counts[char] = (counts[char] || 0) + 1;
  }

  const keys = Object.keys(counts);
  if (keys.length === 0) {
    return {};
  }

  let maxCount = 0;
  for (const key in counts) {
    if (counts[key] > maxCount) {
      maxCount = counts[key];
    }
  }

  const result = {};
  for (const key in counts) {
    if (counts[key] === maxCount) {
      result[key] = counts[key];
    }
  }

  return result;
};
