/**
 * Calculates the total number of times buckets must be lowered to empty all wells.
 * Each row in the grid represents a well.
 * 
 * @param {number[][]} grid - A rectangular grid where 1 represents a unit of water.
 * @param {number} capacity - The capacity of each bucket.
 * @returns {number} - Total number of bucket lowers.
 */
const maxFill = (grid, capacity) => {
  let totalLowers = 0;

  for (let i = 0; i < grid.length; i++) {
    let waterInWell = 0;

    // Count the number of 1s in the current row (well)
    for (let j = 0; j < grid[i].length; j++) {
      if (grid[i][j] === 1) {
        waterInWell++;
      }
    }

    // Calculate how many times the bucket must be lowered for this specific well.
    // We use Math.ceil because any remaining water less than capacity still requires one full lower.
    if (waterInWell > 0) {
      totalLowers += Math.ceil(waterInWell / capacity);
    }
  }

  return totalLowers;
};
```

