const getClosestVowel = (word) => {
  const vowels = 'aeiouAEIOU';
  const isVowel = (char) => vowels.includes(char);

  // Start from the second to last character and move left
  // Vowels at the beginning (index 0) and end (index length-1) don't count
  for (let i = word.length - 2; i > 0; i--) {
    const char = word[i];
    const prev = word[i - 1];
    const next = word[i + 1];

    // Check if current character is a vowel and is surrounded by consonants
    if (isVowel(char) && !isVowel(prev) && !isVowel(next)) {
      return char;
    }
  }

  return "";
};
