const validDate = (date) => {
  if (!date) return false;

  // Validate format mm-dd-yyyy using regex to ensure digits and hyphens
  const regex = /^\d{2}-\d{2}-\d{4}$/;
  if (!regex.test(date)) return false;

  const parts = date.split('-');
  const month = parseInt(parts[0], 10);
  const day = parseInt(parts[1], 10);
  const year = parseInt(parts[2], 10);

  // Rule 3: Months should not be less than 1 or higher than 12
  if (month < 1 || month > 12) return false;

  // Rule 2: Day validation based on month
  if (day < 1) return false;

  if (month === 2) {
    // February: max 29 days
    if (day > 29) return false;
  } else if ([4, 6, 9, 11].includes(month)) {
    // 30-day months
    if (day > 30) return false;
  } else {
    // 31-day months (1, 3, 5, 7, 8, 10, 12)
    if (day > 31) return false;
  }

  return true;
};
