const splitWords = (txt) => {
  // First priority: split on whitespace
  const spaceSplit = txt.split(/\s+/).filter(s => s.length > 0);
  if (txt.includes(' ')) {
    return spaceSplit;
  }

  // Second priority: split on commas
  const commaSplit = txt.split(',').filter(s => s.length > 0);
  if (txt.includes(',')) {
    return commaSplit;
  }

  // Final fallback: count lower-case letters with odd order in alphabet
  // ord('a') = 0 (even), ord('b') = 1 (odd), etc.
  let count = 0;
  for (let i = 0; i < txt.length; i++) {
    const charCode = txt.charCodeAt(i);
    if (charCode >= 97 && charCode <= 122) {
      const alphabetOrder = charCode - 97;
      if (alphabetOrder % 2 !== 0) {
        count++;
      }
    }
  }
  return count;
};
```

