const prodSigns = (arr) => {
  if (arr.length === 0) {
    return null;
  }

  let productOfSigns = 1;
  let sumOfMagnitudes = 0;

  for (let i = 0; i < arr.length; i++) {
    const val = arr[i];

    // Determine sign of current element
    if (val === 0) {
      productOfSigns = 0;
    } else if (val < 0) {
      productOfSigns *= -1;
    }

    // Add magnitude (absolute value) to sum
    sumOfMagnitudes += Math.abs(val);
  }

  return sumOfMagnitudes * productOfSigns;
};
