const tri = (n) => {
  const memo = {};

  const calculate = (i) => {
    if (i === 0) return 1; // Based on example tri(3) = [1, 3, 2, 8], index 0 is 1
    if (i === 1) return 3;
    if (i in memo) return memo[i];

    let result;
    if (i % 2 === 0) {
      result = 1 + i / 2;
    } else {
      // For odd n: tri(n) = tri(n-1) + tri(n-2) + tri(n+1)
      // Since tri(n+1) is even, it can be calculated directly: 1 + (n+1)/2
      result = calculate(i - 1) + calculate(i - 2) + calculate(i + 1);
    }

    memo[i] = result;
    return result;
  };

  const sequence = [];
  for (let i = 0; i <= n; i++) {
    sequence.push(calculate(i));
  }
  return sequence;
};
