const isNested = (string) => {
  let stack = [];
  for (let char of string) {
    if (char === '[') {
      stack.push('[');
    } else if (char === ']') {
      if (stack.length > 0) {
        // If we find a closing bracket and there is more than one 
        // opening bracket in the stack, it means this pair is nested.
        if (stack.length > 1) {
          return true;
        }
        stack.pop();
      }
    }
  }
  return false;
};
