const checkIfLastCharIsALetter = (txt) => {
  if (txt.length === 0) {
    return false;
  }

  const lastChar = txt[txt.length - 1];
  const isLetter = /[a-zA-Z]/.test(lastChar);

  if (!isLetter) {
    return false;
  }

  if (txt.length === 1) {
    return true;
  }

  const secondToLastChar = txt[txt.length - 2];
  return secondToLastChar === ' ';
};
