const checkIfLastCharIsALetter = (txt) => {
  if (!txt) return false;

  // Check if the last character is a letter
  const lastChar = txt.slice(-1);
  const isLetter = /[a-zA-Z]/.test(lastChar);

  if (!isLetter) return false;

  // Check if the character before the last one is a space
  // If the string is only one character long, it is considered not part of a word
  if (txt.length === 1) return true;

  const secondToLastChar = txt.slice(-2, -1);
  return secondToLastChar === ' ';
};
