const wordsInSentence = (sentence) => {
  const isPrime = (num) => {
    if (num < 2) return false;
    for (let i = 2; i * i <= num; i++) {
      if (num % i === 0) return false;
    }
    return true;
  };

  const words = sentence.split(/\s+/);
  const result = [];

  for (let i = 0; i < words.length; i++) {
    if (isPrime(words[i].length)) {
      result.push(words[i]);
    }
  }

  return result.join(' ');
};
