  const getDigitSum = (num) => {
    let sum = 0;
    let n = Math.abs(num);
    while (n > 0) {
      sum += n % 10;
      n = Math.floor(n / 10);
    }
    return sum;
  };

  // We map the numbers to include their original index to ensure a stable sort,
  // as JavaScript's Array.prototype.sort() is stable in modern environments,
  // but explicit index handling guarantees the requirement.
  return nums
    .map((val, index) => ({ val, index, sum: getDigitSum(val) }))
