const getMaxTriples = (n) => {
  // The sequence is a[i] = i^2 - i + 1 for i = 1 to n.
  // We need to find triples (a[i], a[j], a[k]) where i < j < k and (a[i] + a[j] + a[k]) % 3 == 0.
  // Let's analyze a[i] mod 3:
  // i = 1: 1^2 - 1 + 1 = 1  => 1 mod 3
  // i = 2: 2^2 - 2 + 1 = 3  => 0 mod 3
  // i = 3: 3^2 - 3 + 1 = 7  => 1 mod 3
  // i = 4: 4^2 - 4 + 1 = 13 => 1 mod 3
  // i = 5: 5^2 - 5 + 1 = 21 => 0 mod 3
  // i = 6: 6^2 - 6 + 1 = 31 => 1 mod 3
  // Pattern of a[i] mod 3: 1, 0, 1, 1, 0, 1, ...
  // a[i] mod 3 is 0 if i % 3 == 2, and 1 otherwise.

  // Count how many elements have remainder 0 and how many have remainder 1.
  // Remainder 2 is never produced by i^2 - i + 1.

  // i from 1 to n:
  // i % 3 == 2 occurs floor((n + 1) / 3) times.
  // i % 3 == 1 or 0 occurs n - floor((n + 1) / 3) times.

  const count0 = Math.floor((n + 1) / 3);
  const count1 = n - count0;
  const count2 = 0;

  // A sum of three numbers is a multiple of 3 if:
  // 1. All three have the same remainder mod 3.
  // 2. All three have different remainders mod 3 (0, 1, 2).

  // Case 1: All same remainder
  // Triples of 0s: C(count0, 3)
  // Triples of 1s: C(count1, 3)
  // Triples of 2s: C(count2, 3) = 0

  const combinations3 = (m) => {
    if (m < 3) return 0;
    return (m * (m - 1) * (m - 2)) / 6;
  };

  let total = combinations3(count0) + combinations3(count1);

  // Case 2: Different remainders (0, 1, 2)
  // count0 * count1 * count2 = count0 * count1 * 0 = 0

  return total;
};
```

