const getMaxTriples = (n) => {
  // The formula is a[i] = i^2 - i + 1.
  // We need to find triples (a[i], a[j], a[k]) such that (a[i] + a[j] + a[k]) % 3 == 0.
  // This depends only on the values of a[i] modulo 3.

  // Let's analyze a[i] % 3 for i = 1, 2, 3, ...
  // i = 1: 1^2 - 1 + 1 = 1. 1 % 3 = 1
  // i = 2: 2^2 - 2 + 1 = 3. 3 % 3 = 0
  // i = 3: 3^2 - 3 + 1 = 7. 7 % 3 = 1
  // i = 4: 4^2 - 4 + 1 = 13. 13 % 3 = 1
  // i = 5: 5^2 - 5 + 1 = 21. 21 % 3 = 0
  // i = 6: 6^2 - 6 + 1 = 31. 31 % 3 = 1

  // Pattern of a[i] % 3:
  // i % 3 == 1 => 1^2 - 1 + 1 = 1 (mod 3)
  // i % 3 == 2 => 2^2 - 2 + 1 = 3 = 0 (mod 3)
  // i % 3 == 0 => 0^2 - 0 + 1 = 1 (mod 3)

  // So, a[i] % 3 is 0 if i % 3 == 2, and 1 if i % 3 == 1 or 0.
  // Let count0 be the number of elements where a[i] % 3 == 0.
  // Let count1 be the number of elements where a[i] % 3 == 1.
  // Let count2 be the number of elements where a[i] % 3 == 2.

  // From the pattern:
  // count0 = number of i in [1, n] such that i % 3 == 2.
  // count1 = number of i in [1, n] such that i % 3 == 1 or i % 3 == 0.
  // count2 = 0 (since a[i] % 3 is never 2).

  const count0 = Math.floor((n + 1) / 3);
  const count1 = n - count0;
  const count2 = 0;

  // A triple (x, y, z) sums to a multiple of 3 if:
  // 1. All three have the same remainder: (0,0,0), (1,1,1), or (2,2,2)
  // 2. All three have different remainders: (0,1,2)

  const combinations3 = (m) => (m < 3) ? 0 : (m * (m - 1) * (m - 2)) / 6;

  const ways000 = combinations3(count0);
  const ways111 = combinations3(count1);
  const ways222 = combinations3(count2);
  const ways012 = count0 * count1 * count2;

  return ways000 + ways111 + ways222 + ways012;
};
