const doAlgebra = (operator, operand) => {
  // Construct the expression string
  let expression = "";
  for (let i = 0; i < operator.length; i++) {
    expression += operand[i] + " " + operator[i] + " ";
  }
  expression += operand[operand.length - 1];

  // Handle the custom floor division operator '//' 
  // by replacing it with a pattern that performs division and Math.floor
  // Since we need to respect order of operations, we can't simply replace '//' with '/'
  // However, the standard way to evaluate a string in JS is via Function or eval.
  // To handle '//', we replace it with a division and wrap the operation.
  // But for a simpler approach that respects JS precedence:
  // We replace '//' with a custom function call or handle it via a regex.

  // Replace '//' with a division and then we will handle the floor logic.
  // Note: In JS, (a // b) is Math.floor(a / b).
  // To maintain precedence, we can replace 'a // b' with 'Math.floor(a / b)'.
  // Because the problem asks for basic algebra evaluation, we can use a 
  // simple replacement if we assume standard precedence.

  const processedExpression = expression.replace(/\s*(\d+)\s*\/\/\s*(\d+)/g, 'Math.floor($1 / $2)');

  // Use Function constructor to evaluate the string as JavaScript code
  return new Function(`return ${processedExpression}`)();
};
